// DefineStudyTemplatePage.js — PREMIUM GLASS DESIGN + PARTICLES (MATCHING CreateStudyPage)

import React, { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";

function DefineStudyTemplatePage() {
    const { studyId } = useParams();
    const [artifactCount, setArtifactCount] = useState(1);
    const [loading, setLoading] = useState(false);
    const [toasts, setToasts] = useState([]);
    const [particles, setParticles] = useState([]);

    const navigate = useNavigate();

    /* ---------------- PARTICLES ---------------- */
    useEffect(() => {
        const generated = [...Array(55)].map(() => ({
            id: crypto.randomUUID(),
            left: Math.random() * 100,
            top: Math.random() * 100,
            delay: -(Math.random() * 15).toFixed(2),
            duration: 16 + Math.random() * 10,
        }));
        setParticles(generated);
    }, []);

    /* ---------------- TOAST ---------------- */
    const showToast = (text, type = "success") => {
        const id = Date.now();
        setToasts((prev) => [...prev, { id, text, type }]);
        setTimeout(() => {
            setToasts((prev) => prev.filter((t) => t.id !== id));
        }, 3000);
    };

    /* ---------------- SAVE TEMPLATE ---------------- */
    const handleSave = async () => {
        if (artifactCount < 1) {
            showToast("⚠️ Artifact count must be at least 1.", "error");
            return;
        }

        setLoading(true);

        try {
            const token = localStorage.getItem("token");

            const response = await fetch(
                `http://localhost:8080/api/studies/${studyId}/artifact-count`,
                {
                    method: "PATCH",
                    headers: {
                        "Content-Type": "application/json",
                        Authorization: `Bearer ${token}`,
                    },
                    body: JSON.stringify({
                        artifactCountPerTask: artifactCount,
                    }),
                }
            );

            if (!response.ok) throw new Error("Failed");

            showToast("✅ Template saved successfully!");

            setTimeout(() => navigate("/researcher"), 1200);
        } catch (e) {
            showToast("❌ Failed to save template.", "error");
        } finally {
            setLoading(false);
        }
    };


    return (
        <div style={styles.container}>
            {/* PARTICLES */}
            <div style={styles.particles}>
                {particles.map((p) => (
                    <div
                        key={p.id}
                        style={{
                            ...styles.particle,
                            left: `${p.left}%`,
                            top: `${p.top}vh`,
                            animationDelay: `${p.delay}s`,
                            animationDuration: `${p.duration}s`,
                        }}
                    />
                ))}
            </div>

            {/* TOASTS */}
            <div style={styles.toastContainer}>
                {toasts.map((t) => (
                    <div
                        key={t.id}
                        style={{
                            ...styles.toast,
                            ...(t.type === "success"
                                ? styles.toastSuccess
                                : styles.toastError),
                        }}
                    >
                        {t.text}
                    </div>
                ))}
            </div>

            {/* NAVBAR */}
            <div style={styles.navbar}>
                <h2 style={styles.navTitle}>Define Study Template</h2>

                <button
                    className="back-btn"
                    style={styles.backButton}
                    onClick={() => navigate("/researcher")}
                >
                    ← Cancel
                </button>
            </div>

            {/* CARD */}
            <div style={styles.card}>
                <label style={styles.label}>
                    Number of Artifacts Per Task *
                </label>

                <input
                    type="number"
                    min="1"
                    value={artifactCount}
                    onChange={(e) => setArtifactCount(Number(e.target.value))}
                    style={styles.input}
                    disabled={loading}
                />

                <button
                    onClick={handleSave}
                    className="create-btn"
                    style={styles.createBtn}
                    disabled={loading}
                >
                    {loading ? "Saving..." : "Save Template"}
                </button>
            </div>

            {/* KEYFRAMES */}
            <style>
                {`
                    @keyframes floatParticle {
                        0% { transform: translateY(0); opacity: 0.3; }
                        50% { opacity: 0.9; }
                        100% { transform: translateY(-120vh); opacity: 0; }
                    }

                    @keyframes fadeToast {
                        0% { opacity: 0; transform: translateY(-6px); }
                        100% { opacity: 1; transform: translateY(0); }
                    }

                    .create-btn:hover {
                        transform: scale(1.04);
                        box-shadow: 0 0 18px rgba(6,182,212,0.6);
                    }

                    .back-btn:hover {
                        transform: scale(1.05);
                        box-shadow: 0 0 18px rgba(239,68,68,0.7);
                        border-color: rgba(239,68,68,0.8) !important;
                    }
                `}
            </style>
        </div>
    );
}

/* ---------------- STYLES (SAME AS CreateStudyPage) ---------------- */
const styles = {
    container: {
        minHeight: "100vh",
        background: "linear-gradient(135deg, #0a0a0a, #16213e)",
        color: "#fff",
        fontFamily: "Inter, sans-serif",
        position: "relative",
        overflow: "hidden",
        paddingBottom: "40px",
    },

    particles: {
        position: "fixed",
        inset: 0,
        pointerEvents: "none",
        zIndex: 0,
    },

    particle: {
        position: "absolute",
        width: "4px",
        height: "4px",
        background: "linear-gradient(135deg, #06b6d4, #8b5cf6)",
        borderRadius: "50%",
        animation: "floatParticle linear infinite",
        opacity: 0.55,
    },

    navbar: {
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        padding: "20px 40px",
        background: "rgba(255,255,255,0.03)",
        borderBottom: "1px solid rgba(255,255,255,0.1)",
        zIndex: 5,
    },

    navTitle: {
        fontSize: "1.5rem",
        fontWeight: 700,
        color: "#60a5fa",
    },

    backButton: {
        padding: "8px 20px",
        borderRadius: "10px",
        background: "rgba(239,68,68,0.1)",
        border: "2px solid rgba(239,68,68,0.5)",
        color: "#f87171",
        cursor: "pointer",
        fontWeight: 600,
        transition: "all 0.22s ease-out",
    },

    card: {
        width: "90%",
        maxWidth: "760px",
        margin: "40px auto 0 auto",
        background: "rgba(255,255,255,0.05)",
        borderRadius: "18px",
        padding: "40px",
        border: "1px solid rgba(255,255,255,0.12)",
        backdropFilter: "blur(12px)",
        animation: "glowPulse 4s ease infinite",
        position: "relative",
        zIndex: 2,
        display: "flex",
        flexDirection: "column",
        gap: "20px",
    },

    label: {
        fontWeight: 600,
        fontSize: "1rem",
        color: "#93c5fd",
    },

    input: {
        padding: "14px",
        borderRadius: "12px",
        background: "rgba(255,255,255,0.05)",
        border: "1px solid rgba(255,255,255,0.12)",
        color: "white",
        fontSize: "1.1rem",
        fontFamily: "Inter, sans-serif",
        fontWeight: 500,
    },

    createBtn: {
        padding: "14px",
        borderRadius: "12px",
        background: "linear-gradient(135deg, #14b8a6, #06b6d4)",
        border: "none",
        color: "white",
        fontWeight: 700,
        fontSize: "1.05rem",
        boxShadow: "0 0 12px rgba(6,182,212,0.4)",
        cursor: "pointer",
        transition: "all 0.22s ease-out",
    },

    /* Toast Styles */
    toastContainer: {
        position: "fixed",
        top: "20px",
        left: "50%",
        transform: "translateX(-50%)",
        display: "flex",
        flexDirection: "column",
        gap: "12px",
        zIndex: 3000,
        alignItems: "center",
    },

    toast: {
        padding: "14px 22px",
        borderRadius: "10px",
        color: "white",
        fontWeight: 600,
        fontSize: "0.95rem",
        backdropFilter: "blur(10px)",
        boxShadow: "0 4px 16px rgba(0,0,0,0.25)",
        animation: "fadeToast 0.35s ease",
        minWidth: "260px",
        textAlign: "center",
        border: "1px solid rgba(255,255,255,0.2)",
    },

    toastSuccess: {
        background: "rgba(34,197,94,0.25)",
        borderColor: "rgba(34,197,94,0.55)",
    },

    toastError: {
        background: "rgba(239,68,68,0.25)",
        borderColor: "rgba(239,68,68,0.55)",
    },
};

export default DefineStudyTemplatePage;
